"use client";

import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

// --- Types ---
interface QualityOption {
  label: string;
  value: string;
}

interface ColorOption {
  label: string;
  value: string;
  imageUrl: string;
}

// --- Sub-Component: Quality Capsule Row ---
const QualityTray = ({ 
  options, 
  selectedValue, 
  onChange, 
  isOpen, 
  onToggle 
}: { 
  options: QualityOption[]; 
  selectedValue: string | null; 
  onChange: (v: string) => void; 
  isOpen: boolean; 
  onToggle: () => void; 
}) => {
  return (
    <div className="mb-6">
      <AnimatePresence mode="wait">
        {!isOpen ? (
          <motion.button
            key="label"
            initial={{ opacity: 0, y: 5 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -5 }}
            onClick={onToggle}
            className="text-[10px] font-black uppercase tracking-[0.3em] text-white/40 hover:text-white transition-colors"
          >
            Quality: <span className="text-white italic">{selectedValue}</span>
          </motion.button>
        ) : (
          <motion.div
            key="tray"
            initial={{ opacity: 0, x: -10 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 10 }}
            className="flex gap-2 items-center overflow-x-auto no-scrollbar"
          >
            {options.map((opt) => (
              <button
                key={opt.value}
                onClick={() => { onChange(opt.value); onToggle(); }}
                className={`px-4 py-2 rounded-full text-[10px] font-black uppercase italic border transition-all shrink-0 ${
                  selectedValue === opt.value 
                    ? "bg-white border-white text-black" 
                    : "border-white/10 text-white/60 hover:border-white/40"
                }`}
              >
                {opt.label}
              </button>
            ))}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

// --- Sub-Component: Color Image Tray ---
const ColorTray = ({ 
  options, 
  selectedValue, 
  onChange, 
  isOpen, 
  onToggle 
}: { 
  options: ColorOption[]; 
  selectedValue: string | null; 
  onChange: (v: string) => void; 
  isOpen: boolean; 
  onToggle: () => void; 
}) => {
  return (
    <div className="mb-6">
      <AnimatePresence mode="wait">
        {!isOpen ? (
          <motion.button
            key="label"
            initial={{ opacity: 0, y: 5 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -5 }}
            onClick={onToggle}
            className="text-[10px] font-black uppercase tracking-[0.3em] text-white/40 hover:text-white transition-colors"
          >
            Color: <span className="text-white italic">{selectedValue}</span>
          </motion.button>
        ) : (
          <motion.div
            key="tray"
            initial={{ opacity: 0, x: -10 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 10 }}
            className="flex gap-3 items-center"
          >
            {options.map((opt) => (
              <button
                key={opt.value}
                onClick={() => { onChange(opt.value); onToggle(); }}
                className={`group relative flex flex-col items-center gap-2`}
              >
                <div className={`w-12 h-12 rounded-full overflow-hidden border-2 transition-all ${
                  selectedValue === opt.value ? "border-white scale-110" : "border-transparent opacity-50"
                }`}>
                  <img src={opt.imageUrl} className="w-full h-full object-cover" alt={opt.label} />
                </div>
              </button>
            ))}
            <button onClick={onToggle} className="ml-2 text-[10px] font-black uppercase text-white/20">Close</button>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

// --- Main Page ---
export default function ProductPage() {
  const [activeTab, setActiveTab] = useState<string | null>(null);
  const [quality, setQuality] = useState("Premium");
  const [color, setColor] = useState("Phantom");

  const qualityData = [
    { label: "7A Grade", value: "7A" },
    { label: "UA Grade", value: "UA" },
    { label: "1:1 Premium", value: "Premium" },
  ];

  const colorData = [
    { label: "Phantom", value: "Phantom", imageUrl: "https://images.unsplash.com/photo-1542291026-7eec264c27ff?w=100" },
    { label: "University", value: "University", imageUrl: "https://images.unsplash.com/photo-1552346154-21d32810aba3?w=100" },
    { label: "Varsity", value: "Varsity", imageUrl: "https://images.unsplash.com/photo-1606107557195-0e29a4b5b4aa?w=100" },
  ];

  return (
    <div className="min-h-screen bg-[#050505] text-white flex flex-col items-center justify-center p-6">
      <div className="w-full max-w-[320px]">
        
        {/* Product Info - Updates based on state */}
        <div className="mb-12">
          <h1 className="text-4xl font-black uppercase italic tracking-tighter leading-none mb-2">
            AJ1 {color}
          </h1>
          <p className="text-[10px] font-black uppercase tracking-[0.5em] text-white/20">
            {quality} Edition
          </p>
        </div>

        {/* Dynamic Selectors */}
        <QualityTray 
          options={qualityData}
          selectedValue={quality}
          onChange={setQuality}
          isOpen={activeTab === "quality"}
          onToggle={() => setActiveTab(activeTab === "quality" ? null : "quality")}
        />

        <ColorTray 
          options={colorData}
          selectedValue={color}
          onChange={setColor}
          isOpen={activeTab === "color"}
          onToggle={() => setActiveTab(activeTab === "color" ? null : "color")}
        />

        {/* Pure Display Price */}
        <div className="mt-12 pt-6 border-t border-white/5">
          <p className="text-2xl font-black italic">$240.00</p>
        </div>
      </div>
    </div>
  );
}